import type { AccordionContentProps } from "../accordion.types";

import { forwardRef, useRef, useEffect, useState } from "react";
import { getTransitionDurationInMs } from "@system";
import { clsx } from "clsx";

import { useAccordionSection } from "../hooks/use-accordion-section";
import { AccordionClasses } from "../accordion.styles";

export const AccordionContent = forwardRef<HTMLDivElement, AccordionContentProps>(
  ({ children, className, indent, ...props }, ref) => {
    const { isExpanded, sectionId, buttonId } = useAccordionSection();
    const contentRef = useRef<HTMLDivElement | null>(null);
    const [height, setHeight] = useState(0);

    useEffect(() => {
      const element = contentRef.current;
      if (element) {
        if (isExpanded) {
          element.style.maxHeight = `${height + element.scrollHeight}px`;
        } else {
          element.style.maxHeight = `${height + element.scrollHeight}px`;
          void element.offsetHeight;
          element.style.maxHeight = "0px";
        }
      }
    }, [isExpanded, height]);

    useEffect(() => {
      const observer = new ResizeObserver((entries) => {
        const observedElement = entries[0];
        setTimeout(() => {
          setHeight(observedElement.contentRect.height);
        }, getTransitionDurationInMs(observedElement.target));
      });
      const element = contentRef.current;

      if (element) {
        observer.observe(element);
      }

      return () => {
        if (element) {
          observer.unobserve(element);
        }
      };
    }, []);

    useEffect(() => {
      if (contentRef.current) {
        if (!isExpanded) {
          contentRef.current.setAttribute("inert", "true");
        } else {
          contentRef.current.removeAttribute("inert");
        }
      }
    }, [isExpanded]);

    const handleRef = (node: HTMLDivElement | null) => {
      contentRef.current = node;
      if (typeof ref === "function") {
        ref(node);
      } else if (ref) {
        ref.current = node;
      }
    };

    return (
      <div
        ref={handleRef}
        aria-hidden={!isExpanded}
        aria-labelledby={buttonId}
        className={clsx(AccordionClasses.contentContainer, className)}
        data-expanded={isExpanded}
        data-testid="accordion-content-region"
        id={sectionId}
        role="region"
        {...props}
      >
        <div className={AccordionClasses.contentInner} style={{ paddingInlineStart: indent }}>
          {children}
        </div>
      </div>
    );
  },
);

AccordionContent.displayName = "Accordion.Content";
